"""Prepare an opt-in PageBlock test copy of the single full package; never publish it."""
import hashlib
import json
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]

def package():
    output = ROOT / 'dist/l4d2-pageblock-drop-experiment'
    if output.exists():
        raise FileExistsError(f'Preserve or move the existing experiment first: {output}')
    source = ROOT / 'dist/l4d2-bridge'
    # The normal full build already contains the matched trio and optional DLL.
    target_relative = 'optional/L4N/L4D2BridgePlugin.dll'
    if not (source / target_relative).is_file():
        raise FileNotFoundError('Build the complete package before preparing a PageBlock experiment')
    shutil.copytree(source, output)
    target = output / target_relative
    (output / 'PAGEBLOCK-DROP-GC.md').write_text('# PageBlock experiment\n\nRead [setup, coverage and validation](docs/PAGEBLOCK-RESIDENCY-EXPERIMENT.md) and [Drop/GC controls](docs/PAGEBLOCK-DROP-GC.md).\n')
    shutil.copy2(ROOT / 'config/PAGEBLOCK-DROP.conf', output / 'PAGEBLOCK-DROP.conf')
    # These binaries are experimental; avoid presenting the stable patch guide as their entry point.
    (output / 'PATCH-INSTRUCTIONS.md').unlink(missing_ok=True)
    version = (ROOT / 'VERSION').read_text().strip()
    (output / 'EXPERIMENTAL.txt').write_text(f'{version}: unified PageBlock residency/reclaim experiment; not an official release. Read docs/PAGEBLOCK-RESIDENCY-EXPERIMENT.md.\n')
    hashes = json.loads((output / 'SHA256.json').read_text())
    hashes[target_relative] = hashlib.sha256(target.read_bytes()).hexdigest()
    (output / 'SHA256.json').write_text(json.dumps(hashes, indent=2) + '\n')
    receipt = json.loads((output / 'BUILD-INFO.json').read_text())
    receipt.update(kind='pageblock-residency-full-experiment', optional_plugin=True, files=hashes)
    (output / 'BUILD-INFO.json').write_text(json.dumps(receipt, indent=2) + '\n')
    print(output)

if __name__ == '__main__':
    package()
